import app from 'flarum/forum/app';
import { extend, override } from 'flarum/common/extend';
import LinkButton from 'flarum/common/components/LinkButton';
import Icon from 'flarum/common/components/Icon';
import listItems from 'flarum/common/helpers/listItems';
import Veil from './components/Veil';
import { shieldOf, t, loadChunk, openProgress } from './util';

/*
 * forum.js is on every page, so it only does what every page needs: drawing
 * a hidden discussion or post as a veil (the words never arrived, the server
 * kept them), the small marks on visible ones, the composer chips and the
 * route. The modals and the progress page are a lazy chunk.
 */

/** The composer's choice: undefined = automatic, null = no mark, or a work and position. */

const chip = (label, onclick, active) => m("button", {
  type: "button",
  className: 'Button SpoilerShield-chip' + (active ? ' SpoilerShield-chip--active' : ''),
  onclick: onclick
}, m(Icon, {
  name: "fas fa-user-secret"
}), m("span", {
  className: "Button-label"
}, label));
app.initializers.add('ernestdefoe/spoiler-shield', () => {
  app.routes['spoiler-shield'] = {
    path: '/spoilers',
    component: () => loadChunk().then(async c => (await c.loadCore(), c))
  };

  // ---- The discussion list --------------------------------------------------
  extend('flarum/forum/components/DiscussionListItem', 'elementAttrs', function (attrs) {
    if (shieldOf(this.attrs.discussion)?.hidden) attrs.className = (attrs.className || '') + ' SpoilerShield-hiddenItem';
  });

  // A hidden discussion isn't a link (there'd be nothing to read): its title is the veil.
  override('flarum/forum/components/DiscussionListItem', 'mainView', function (original) {
    const discussion = this.attrs.discussion;
    const shield = shieldOf(discussion);
    if (!shield?.hidden) return original();
    return m("div", {
      className: "DiscussionListItem-main SpoilerShield-main"
    }, m("h2", {
      className: "DiscussionListItem-title"
    }, m(Veil, {
      shield: shield,
      type: "discussions",
      id: discussion.id(),
      compact: true
    })), m("ul", {
      className: "DiscussionListItem-info"
    }, listItems(this.infoItems().toArray())));
  });

  // Visible but marked: where it sits (Marquee already shows its own episode label).
  extend('flarum/forum/components/DiscussionListItem', 'infoItems', function (items) {
    const shield = shieldOf(this.attrs.discussion);
    if (!shield || shield.hidden || !shield.label || shield.work.startsWith('mq:')) return;
    items.add('spoilerShield', m("span", {
      className: "SpoilerShield-mark",
      title: String(t('mark.title', {
        work: shield.title
      }))
    }, m(Icon, {
      name: "fas fa-user-secret"
    }), " ", shield.label), 5);
  });

  // ---- The discussion page ----------------------------------------------------
  extend('flarum/forum/components/DiscussionHero', 'items', function (items) {
    const discussion = this.attrs.discussion;
    const shield = shieldOf(discussion);
    if (!shield?.hidden || !items.has('title')) return;
    items.setContent('title', m("h1", {
      className: "DiscussionHero-title SpoilerShield-heroTitle"
    }, m(Veil, {
      shield: shield,
      type: "discussions",
      id: discussion.id()
    })));
  });

  // Where you're up to in this discussion's work, and the way to change it.
  extend('flarum/forum/components/DiscussionPage', 'sidebarItems', function (items) {
    const discussion = this.discussion;
    const shield = shieldOf(discussion);
    if (!shield || !app.session.user) return;
    items.add('spoilerShield', m("div", {
      className: "SpoilerShield-progressCard"
    }, m("div", {
      className: "SpoilerShield-progressCard-work"
    }, m(Icon, {
      name: "fas fa-user-secret"
    }), " ", shield.title), m("div", {
      className: "SpoilerShield-progressCard-at"
    }, shield.viewer ? t('sidebar.you_are_at', {
      label: shield.viewer.label
    }) : t('sidebar.not_set')), m("button", {
      type: "button",
      className: "Button Button--block",
      onclick: () => openProgress(shield.work)
    }, shield.viewer ? t('sidebar.change') : t('sidebar.set'))), -20);
  });

  // ---- Posts --------------------------------------------------------------------
  override('flarum/forum/components/CommentPost', 'content', function (original) {
    const post = this.attrs.post;
    const shield = shieldOf(post);
    const items = original();
    if (!shield?.hidden || this.isEditing()) return items;

    // The post's header stays (who, when); its body is the veil.
    return items.flatMap(vnode => vnode && vnode.attrs && 'contentHtml' in vnode.attrs ? [m(vnode.tag, {
      ...vnode.attrs,
      contentHtml: ''
    }), m(Veil, {
      shield: shield,
      type: "posts",
      id: post.id(),
      compact: !!shieldOf(post.discussion())?.hidden
    })] : [vnode]);
  });
  extend('flarum/forum/components/CommentPost', 'headerItems', function (items) {
    const shield = shieldOf(this.attrs.post);
    if (!shield || shield.hidden || !shield.label) return;
    items.add('spoilerShield', m("span", {
      className: "SpoilerShield-mark",
      title: String(t('mark.title', {
        work: shield.title
      }))
    }, m(Icon, {
      name: "fas fa-user-secret"
    }), " ", shield.revealed ? t('mark.revealed', {
      label: shield.label
    }) : shield.label), -10);
  });

  // ---- The composer ---------------------------------------------------------------
  // A new discussion: none, or a work and a place in it. Below the title (phones lift the first item).
  extend('flarum/forum/components/DiscussionComposer', 'headerItems', function (items) {
    const fields = this.composer.fields;
    const choice = fields.spoilerShield;
    const label = choice ? choice.label ? `${choice.title} · ${choice.label}` : choice.title : fields.marquee ? t('composer.from_marquee') : t('composer.mark');
    items.add('spoilerShield', chip(label, () => loadChunk().then(c => app.modal.show(c.MarkModal, {
      choice,
      onchoose: next => {
        fields.spoilerShield = next;
        m.redraw();
      }
    })), !!choice), -10);
  });
  extend('flarum/forum/components/DiscussionComposer', 'data', function (data) {
    const choice = this.composer.fields.spoilerShield;
    if (choice !== undefined) data.spoilerShield = choice && {
      work: choice.work,
      position: choice.position
    };
  });

  // A reply in a discussion with a place: it's stamped with yours unless you say otherwise.
  extend('flarum/forum/components/ReplyComposer', 'headerItems', function (items) {
    const shield = shieldOf(this.attrs.discussion);
    if (!shield || !app.session.user) return;
    const fields = this.composer.fields;
    const choice = fields.spoilerShield;
    const ahead = shield.viewer && (shield.position === null || shield.viewer.position > shield.position);
    const label = choice === null ? t('composer.reply_nothing_past', {
      label: shield.label || shield.title
    }) : choice ? t('composer.reply_at', {
      label: choice.label
    }) : shield.position !== null && ahead ? t('composer.reply_at', {
      label: shield.viewer.label
    }) : t('composer.reply_mark');
    items.add('spoilerShield', chip(label, () => loadChunk().then(c => app.modal.show(c.MarkModal, {
      reply: shield,
      choice,
      onchoose: next => {
        fields.spoilerShield = next;
        m.redraw();
      }
    })), choice !== undefined || !!(shield.position !== null && ahead)), -10);
  });
  extend('flarum/forum/components/ReplyComposer', 'data', function (data) {
    const choice = this.composer.fields.spoilerShield;
    if (choice !== undefined) data.spoilerShield = choice && {
      position: choice.position
    };
  });

  // ---- The way to the progress page ------------------------------------------------
  extend('flarum/forum/components/SessionDropdown', 'items', function (items) {
    items.add('spoilerShield', m(LinkButton, {
      icon: "fas fa-user-secret",
      href: app.route('spoiler-shield')
    }, t('nav.progress')), 55);
  });
});